def is_balanced(s):
    stack = []
    brackets = {')': '(', ']': '[', '}': '{'}
    for bracket in s:
        if bracket in brackets:
            if not stack or stack.pop() != brackets[bracket]:
                return False
        else:
            stack.append(bracket)
    return not stack
