def longest_common_prefix(strs):
    if not strs:
        return ""

    min_len = min(len(s) for s in strs)
    prefix = ""

    for i in range(min_len):
        c = strs[0][i]
        for s in strs[1:]:
            if s[i] != c:
                prefix = prefix[:i]
                break
        if not prefix:
            break
    return prefix
```

