def longest_common_prefix(strings: list[str]) -> str:
    if not strings:
        return ""

    for i in range(len(strings[0])):
        c = strings[0][i]
        for s in strings[1:]:
            if i >= len(s) or s[i] != c:
                return strings[0][:i]
    return strings[0]
